'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=process.env.RECHERCHE_PERSONNAGE_ASSET_DIR||path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
function functions(s){return parse(s).body.filter(n=>n.type==='FunctionDeclaration'&&['chargerPersonnageParNom','t','rafraichirEcranCreationApresChangementLangue'].includes(n.id.name)).map(n=>s.slice(n.start,n.end)).join('\n');}
test('recherche : 324 bascules sur douze chemins, neuf langues et 320/390/1280 sans répétition de requête ni redirection',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:800}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>r.fulfill({contentType:'text/html',body:read('index.html').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'')}));await page.goto('https://fixture.invalid/index.html');await page.addStyleTag({content:read('style.css')});
 for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/connection-resources.js','i18n/i18n-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:'let _currentScreenIndex=0;\n'+functions(read('creation.js'))+'\nwindow.RP_I18N_ON_LANGUAGE_CHANGE=rafraichirEcranCreationApresChangementLangue;'});
 await page.evaluate(()=>{window.calls=[];window.redirects=[];window.state={pa:20,arg:300,progression:{stage:2}};const original=setTimeout;window.setTimeout=(f,ms,...args)=>ms===1000?(redirects.push({delay:ms}),redirects.length):original(f,ms,...args);window.fetch=()=>{throw Error('Réseau réel interdit');};window.rpMarquerProprietaireCache=()=>calls.push(['cacheOwner']);window.snapshot=()=>JSON.stringify({calls,redirects,state,hash:location.hash,href:location.href,session:JSON.stringify(sessionStorage),storage:Object.fromEntries(Object.entries(localStorage).filter(([k])=>!k.includes('lang'))),name:document.getElementById('retrouver-nom').value,focus:document.activeElement.id,start:document.getElementById('retrouver-nom').selectionStart,end:document.getElementById('retrouver-nom').selectionEnd});document.getElementById('retrouver-panel').style.display='block';});
 const cases=['required','unavailable','notFound','connectionError','owned','already','alreadyEmpty','http','denied','unknown','pending','success'];
 for(const mode of cases){const before=await page.evaluate(async mode=>{changerLangueRP('fr');calls.length=0;redirects.length=0;localStorage.clear();sessionStorage.setItem('fixture','conservé');document.getElementById('retrouver-nom').value=mode==='required'?'':'Nom <原 & اسم>';document.getElementById('retrouver-nom').focus();document.getElementById('retrouver-nom').setSelectionRange(2,6);
 const loaded={char:{name:'Nom canonique <原 & اسم>',photoUrl:'fixture.webp'},country:'republic',currentCity:'ville_a',arg:300,inf:2,pop:3,dis:4};window.sbLoadPersonnage=async(...a)=>{calls.push(['load',...a]);if(mode==='pending')return new Promise(r=>window.resolveLoad=r);if(mode==='notFound')return null;if(mode==='connectionError')throw Error('fixture');return loaded;};if(mode==='unavailable')delete window.sbLoadPersonnage;window.rpAuthAssurerSession=async()=>{calls.push(['session']);return {fixture:true};};window.rpAuthRattacherPersonnage=async(...a)=>{calls.push(['claim',...a]);const verdicts={owned:{ok:false,raison:'personnage_deja_possede'},already:{ok:false,raison:'compte_deja_pourvu',personnage:'Nom « <原 & اسم> »'},alreadyEmpty:{ok:false,raison:'compte_deja_pourvu'},http:{ok:false,raison:'http_404'},denied:{ok:false,raison:'raison libre <à conserver>'},unknown:{ok:false}};return verdicts[mode]||{ok:true};};window.pending=chargerPersonnageParNom();if(mode!=='pending')await pending;return {snapshot:snapshot(),calls:calls.map(x=>x[0]),key:document.getElementById('retrouver-msg').dataset.i18n};},mode);
 assert.deepEqual(before.calls,['required','unavailable'].includes(mode)?[]:['notFound','connectionError','pending'].includes(mode)?['load']:mode==='success'?['load','session','claim','cacheOwner']:['load','session','claim']);
 for(const lang of langs){const got=await page.evaluate(({lang})=>{changerLangueRP(lang);const el=document.getElementById('retrouver-msg'),values=JSON.parse(el.dataset.i18nValues||'{}');return {same:snapshot(),body:el.textContent,expected:i18next.t(el.dataset.i18n,{values,replace:{...values,values}}),dir:el.dir,html:el.innerHTML,overflow:document.documentElement.scrollWidth>innerWidth};},{lang});assert.equal(got.same,before.snapshot,mode+'/'+lang);assert.equal(got.body,got.expected);assert.equal(got.dir,lang==='ar'?'rtl':'');assert.equal(got.overflow,false,mode+'/'+lang+'/'+width);if(mode==='already')assert.ok(got.body.includes('Nom « <原 & اسم> »'));if(mode==='denied')assert.ok(got.body.includes('raison libre <à conserver>'));if(mode==='success')assert.ok(got.body.includes('Nom <原 & اسم>'));assert.ok(!got.html.includes('<原'));}
 if(mode==='pending'){await page.evaluate(async()=>{resolveLoad(null);await pending;});assert.equal(await page.locator('#retrouver-msg').getAttribute('data-i18n'),'home.findCharacterNotFound');}}
 // Standard replace supports both conventions; values named like options cannot change language/namespace.
 const interpolation=await page.evaluate(()=>{i18next.addResource('fr','translation','fixture.test','{{name}} / {{values.name}} / {{lng}} / {{ns}}');const n=document.createElement('div');n.dataset.i18n='fixture.test';n.dataset.i18nValues=JSON.stringify({name:'Nom " <原 & اسم>',lng:'ar',ns:'autre'});document.body.append(n);changerLangueRP('fr');const result={text:n.textContent,language:i18next.language};n.remove();return result;});assert.deepEqual(interpolation,{text:'Nom " <原 & اسم> / Nom " <原 & اسم> / ar / autre',language:'fr'});
 await page.evaluate(async()=>{changerLangueRP('fr');document.getElementById('retrouver-nom').value='';await chargerPersonnageParNom();const d=i18next.getResourceBundle('de','translation');delete d.home.findCharacterEnterName;i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',d);changerLangueRP('de');});assert.equal(await page.locator('#retrouver-msg').textContent(),await page.evaluate(()=>RP_I18N_RESOURCES.fr.translation.home.findCharacterEnterName));assert.deepEqual(errors,[]);await page.close();}}finally{await browser.close();}
});
